-- 給付項目更新（新商品或有變動，81 款）（tool/benefit_items/build_seed_sql.py 產生，不要手改）
-- 在 Supabase SQL Editor 整份貼上執行；可重複執行

DROP TABLE IF EXISTS benefit_items_import;
CREATE TEMP TABLE benefit_items_import (
  company_code TEXT, product_name TEXT, item_order INTEGER,
  item_key TEXT, item_name TEXT, formula TEXT, source_excerpt TEXT
);


-- 先刪掉這些商品舊的項目，再寫入新的
DELETE FROM public.insurance_product_benefit_items i
USING public.insurance_products p
WHERE i.product_id = p.id
  AND (p.company_code, p.product_name) IN (SELECT DISTINCT company_code, product_name FROM benefit_items_import);

SELECT p.id, v.item_order, v.item_key, v.item_name, v.formula, v.source_excerpt
FROM benefit_items_import v
JOIN public.insurance_products p ON p.company_code = v.company_code AND p.product_name = v.product_name;

DROP TABLE benefit_items_import;

-- 檢查：目前資料表一共幾款商品、幾個項目（數字應該和工具印出的一樣）
SELECT count(DISTINCT product_id) AS product_count, count(*) AS item_count, count(formula) AS with_formula
FROM public.insurance_product_benefit_items;
