INSERT INTO benefit_items_import VALUES
  ('cathay', '國泰人壽新GO心保障100定期壽險', 1, '身故', '身故保險金', '保額 × 1', '第十條身故或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按保險單上所記載的保險金額(不含其他附約、附加條款、批註條款)，給付身故保險金。'),
  ('cathay', '國泰人壽新GO心保障100定期壽險', 2, '完全失能', '完全失能保險金', '保額 × 1', '第十一條完全失能保險金的給付及其限制被保險人於本契約有效期間內致成附表一所列完全失能程度之一者，本公司按保險單上所記載的保險金額(不含其他附約、附加條款、批註條款)，給付完全失能保險金。'),
  ('cathay', '國泰人壽新GO心保障100定期壽險', 3, '意外事故失能', '意外事故失能保險金', '保額 × 附表比例', '第十二條意外事故失能保險金的給付及其限制被保險人於本契約有效期間內遭受第二條約定的意外傷害事故，自意外傷害事故發生之日起一百八十日以內致成附表二所列失能程度之一者，本公司按失能診斷確定日之保險金額(不含其他附約、附加條款、批註條款)為準，依附表二所列比例計算，給付意外事故失能保險金。'),
  ('cathay', '國泰人壽新GO安心保本定期保險', 1, '完全失能', '完全失能保險金', '取較高：保額 × 1／保單價值／其他算法', '第十二條完全失能保險金的給付及限制被保險人於本契約有效期間內致成附表二所列完全失能程度之一並經診斷確定者，本公司將按失能診斷確定日時下列三款金額之最大者給付完全失能保險金：一、保險單上所記載的保險金額。二、保單價值準備金乘以「門檻比率」。三、以本契約(不含其他附約)保險單上所記載保險金額為準，按年繳繳費方式無息計算自契約生效日起至「被保險人失能診斷確定日」或「原定繳費期間屆滿日」二者較早屆至之日所應繳保險費總額的一點零六倍。被保險人於本契約有效且於繳費期間內致成前項之完全失能並經診斷確定者，本公司另加計按日數比例計算當期已繳付之未到期保險費，併入完全失能保險金內給付。被保險人同時或先後致成附表二所列二項以上之完全失能程度者，本公司只給付一項完全失能保險金。第一項所稱「門檻比率」係指'),
  ('cathay', '國泰人壽新GO安心保本定期保險', 2, '滿期', '滿期保險金', '依已繳保費計算（看原文）', '第十條滿期保險金的給付被保險人於本契約有效且保險年齡到達八十六歲之保險單週年日仍生存者，本公司按本契約（不含其他附約）保險單上所記載「保險金額」為準，按年繳繳費方式無息計算自契約生效日起至「原定繳費期間屆滿日」所應繳保險費總額，給付滿期保險金。'),
  ('cathay', '國泰人壽新GO安心保本定期保險', 3, '身故', '身故保險金', '取較高：保額 × 1／保單價值／其他算法', '第十一條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司將按身故日時下列三款金額之最大者給付身故保險金：一、保險單上所記載的保險金額。二、保單價值準備金乘以「門檻比率」。三、以本契約(不含其他附約)保險單上所記載保險金額為準，按年繳繳費方式無息計算自契約生效日起至「被保險人身故日」或「原定繳費期間屆滿日」二者較早屆至之日所應繳保險費總額的一點零六倍。被保險人於本契約有效且於繳費期間內身故者，本公司另加計按日數比例計算當期已繳付之未到期保險費，併入身故保險金內給付。訂立本契約時，以未滿十五足歲之未成年人為被保險人，除喪葬費用之給付外，其餘死亡給付之約定於被保險人滿十五足歲之日起發生效力；被保險人滿十五足歲前死亡者，其'),
  ('cathay', '國泰人壽微型個人定期壽險', 1, '身故', '身故保險金', '保額 × 1', '第十條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按身故日時，本契約保險單上所記載之保險金額，給付「身故保險金」。'),
  ('cathay', '國泰人壽微型個人定期壽險', 2, '完全失能', '完全失能保險金', '保額 × 1', '第十一條完全失能保險金的給付及限制被保險人於本契約有效期間內致成附表所列完全失能程度之一者，本公司按完全失能診斷確定日時，本契約保險單上所記載之保險金額，給付「完全失能保險金」。'),
  ('cathay', '國泰人壽心iLife一年期定期壽險', 1, '身故', '身故保險金', '保額 × 1', '第十一條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按身故日計算「當年度保險金額」給付「身故保險金」。'),
  ('cathay', '國泰人壽心iLife一年期定期壽險', 2, '完全失能', '完全失能保險金', '保額 × 1', '第十二條完全失能保險金的給付及限制被保險人於本契約有效期間內致成附表所列完全失能程度之一者，本公司按完全失能診斷確定日計算「當年度保險金額」給付「完全失能保險金」。'),
  ('cathay', '國泰人壽豪美利101利率變動型美元終身壽險(定期給付型)', 1, '身故', '身故保險金或喪葬費用保險金', '保額 × 1', '第十八條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按身故日之「總保險金額」，給付「身故保險金」。'),
  ('cathay', '國泰人壽豪美利101利率變動型美元終身壽險(定期給付型)', 2, '祝壽', '祝壽保險金', '保額 × 1', '第十七條祝壽保險金的給付被保險人於本契約有效期間且保險年齡到達一百零五歲之保險單週年日仍生存時，本公司按保險年齡一百零四歲之保險單年度末的「總保險金額」，給付「祝壽保險金」。'),
  ('cathay', '國泰人壽豪美利101利率變動型美元終身壽險(定期給付型)', 3, '完全失能', '完全失能保險金', '保額 × 1', '第十九條完全失能保險金的給付及限制被保險人於本契約有效期間內致成附表一所列完全失能程度之一者，本公司按完全失能診斷確定日之「總保險金額」，給付「完全失能保險金」。'),
  ('cathay', '國泰人壽享保障微型個人定期壽險', 1, '身故', '身故保險金', '保額 × 1', '第九條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按身故日時，本契約保險單上所記載之保險金額，給付「身故保險金」。'),
  ('cathay', '國泰人壽享保障微型個人定期壽險', 2, '完全失能', '完全失能保險金', '保額 × 1', '第十條完全失能保險金的給付及限制被保險人於本契約有效期間內致成附表所列完全失能程度之一者，本公司按完全失能診斷確定日時，本契約保險單上所記載之保險金額，給付「完全失能保險金」。'),
  ('cathay', '國泰人壽祿利澳翔利率變動型澳幣終身壽險', 1, '身故', '身故保險金或喪葬費用保險金', '取較高：保額 × 1／保單價值', '第十七條身故保險金或喪葬費用保險金的給付被保險人於本契約有效且於繳費期間內身故者，本公司按身故日，下列二款計算方式所得金額之較大者，給付身故保險金，且當期已繳付之未到期保險費將不予退還：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。被保險人於本契約有效期間且於繳費期滿後身故者，本公司按身故日，下列三款計算方式所得金額之最大者，給付身故保險金：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。三、「年繳應繳保險費總額」。訂立本契約時，以未滿十五足歲之未成年人為被保險人，除喪葬費用之給付外，其餘死亡給付之約定於被保險人滿十五足歲之日起發生效力；被保險人滿十五足歲前死亡者，其身故保險金變更為喪葬費用保險金。前項未滿十五足歲之被保險人'),
  ('cathay', '國泰人壽祿利澳翔利率變動型澳幣終身壽險', 2, '祝壽', '祝壽保險金', '保額 × 1', '第十六條祝壽保險金的給付被保險人於本契約有效期間且保險年齡到達一百零五歲之保險單週年日仍生存時，本公司按保險年齡一百零四歲之「當年度保險金額」，給付祝壽保險金。'),
  ('cathay', '國泰人壽祿利澳翔利率變動型澳幣終身壽險', 3, '完全失能', '完全失能保險金', '取較高：保額 × 1／保單價值', '第十八條完全失能保險金的給付及限制被保險人於本契約有效且於繳費期間內致成附表三所列完全失能程度之一者，本公司按完全失能診斷確定日，下列二款計算方式所得金額之較大者，給付完全失能保險金，且當期已繳付之未到期保險費將不予退還：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。被保險人於本契約有效期間且於繳費期滿後致成附表三所列完全失能程度之一者，本公司按完全失能診斷確定日，下列三款計算方式所得金額之最大者，給付完全失能保險金：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。三、「年繳應繳保險費總額」。被保險人同時或先後致成附表三所列二項以上之完全失能程度者，本公司僅給付一項完全失能保險金。第十九條保險事故的通知與保險金的申請時間要保人或受益人應於知悉本公司應負保險責任'),
  ('cathay', '國泰人壽澳利成雙利率變動型澳幣終身壽險', 1, '身故', '身故保險金或喪葬費用保險金', '取較高：保額 × 1／保單價值', '第十七條身故保險金或喪葬費用保險金的給付被保險人於本契約有效且於繳費期間內身故者，本公司按身故日，下列二款計算方式所得金額之較大者，給付身故保險金，且當期已繳付之未到期保險費將不予退還：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。被保險人於本契約有效期間且於繳費期滿後身故者，本公司按身故日，下列三款計算方式所得金額之最大者，給付身故保險金：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。三、「年繳應繳保險費總額」。訂立本契約時，以未滿十五足歲之未成年人為被保險人，除喪葬費用之給付外，其餘死亡給付之約定於被保險人滿十五足歲之日起發生效力；被保險人滿十五足歲前死亡者，其身故保險金變更為喪葬費用保險金。前項未滿十五足歲之被保險人'),
  ('cathay', '國泰人壽澳利成雙利率變動型澳幣終身壽險', 2, '祝壽', '祝壽保險金', '保額 × 1', '第十六條祝壽保險金的給付被保險人於本契約有效期間且保險年齡到達一百零五歲之保險單週年日仍生存時，本公司按保險年齡一百零四歲之「當年度保險金額」，給付祝壽保險金。'),
  ('cathay', '國泰人壽澳利成雙利率變動型澳幣終身壽險', 3, '完全失能', '完全失能保險金', '取較高：保額 × 1／保單價值', '第十八條完全失能保險金的給付及限制被保險人於本契約有效且於繳費期間內致成附表三所列完全失能程度之一者，本公司按完全失能診斷確定日，下列二款計算方式所得金額之較大者，給付完全失能保險金，且當期已繳付之未到期保險費將不予退還：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。被保險人於本契約有效期間且於繳費期滿後致成附表三所列完全失能程度之一者，本公司按完全失能診斷確定日，下列三款計算方式所得金額之最大者，給付完全失能保險金：一、「當年度保險金額」。二、「保單價值準備金」乘以「門檻比率」。三、「年繳應繳保險費總額」。被保險人同時或先後致成附表三所列二項以上之完全失能程度者，本公司僅給付一項完全失能保險金。第十九條保險事故的通知與保險金的申請時間要保人或受益人應於知悉本公司應負保險責任'),
  ('cathay', '國泰人壽繽利101利率變動型終身壽險（定期給付型）', 1, '身故', '身故保險金或喪葬費用保險金', '保額 × 1', '第十四條身故保險金或喪葬費用保險金的給付被保險人於本契約有效期間內身故者，本公司按身故日之「總保險金額」，給付「身故保險金」。'),
